1	-- =============================================================================
2	-- Gidape ERP — COMMENT ON TABLE / COMMENT ON COLUMN (pt-BR)
3	-- Tabelas que já possuíam comentário foram omitidas. Strings com '' escapadas.
4	-- =============================================================================
5	
6	-- ============================== TABELAS ======================================
7	
8	-- núcleo / multi-loja
9	COMMENT ON TABLE public.lojas IS 'Cadastro das lojas/unidades (multi-loja). 1=Fábrica,2=Asa Sul,3=Asa Norte,4=Lago Sul,5=Águas Claras,6=Brasília Shopping.';
10	
11	-- estoque & movimentações
12	COMMENT ON TABLE public.categorias IS 'Categorias de produtos (com emoji e setor), usadas para classificar produtos e produtos_master por loja.';
13	COMMENT ON TABLE public.produtos IS 'Catálogo legado de produtos por loja (modelo antigo). Substituído gradualmente por produtos_master + produto_loja_visibility.';
14	COMMENT ON TABLE public.produtos_master IS 'Catálogo mestre unificado de produtos (source of truth). codigo_interno é a chave de negócio; ativo=true define produtos válidos.';
15	COMMENT ON TABLE public.estoque IS 'Saldo atual de estoque por produto e por loja, com mínimo/máximo para alertas. 1 linha por produto_master_id x loja_id.';
16	COMMENT ON TABLE public.movimentacoes IS 'Razão de todas as movimentações de estoque (entradas, saídas, ajustes, perdas). Log append-only que alimenta saldos e auditoria.';
17	COMMENT ON TABLE public.movimentacao_anexos IS 'Anexos (comprovantes/documentos) vinculados a uma movimentação de estoque.';
18	COMMENT ON TABLE public.alertas_estoque IS 'Alertas gerados quando estoque cruza mínimo/máximo (ex.: estoque baixo, ruptura). Marcados como resolvidos ao normalizar.';
19	COMMENT ON TABLE public.setores IS 'Setores operacionais (ex.: produção, confeitaria) usados para classificar produtos, categorias e etapas.';
20	COMMENT ON TABLE public.lotes IS 'Lotes de produto com código, validade e fabricação. Base da rastreabilidade por validade (shelf-life curto, doces saudáveis).';
21	COMMENT ON TABLE public.estoque_lotes IS 'Saldo de estoque por lote e por loja (quanto resta de cada lote em cada unidade).';
22	COMMENT ON TABLE public.perdas IS 'Registro de perdas/quebras de produto (motivo, valor estimado, foto), com fluxo de verificação. Multi-loja.';
23	COMMENT ON TABLE public.perdas_produtos IS 'Lista de produtos elegíveis para registro de perdas (catálogo auxiliar da tela de Perdas).';
24	COMMENT ON TABLE public.produto_loja_visibility IS 'Define quais produtos_master estão visíveis/ativos em cada loja. Sem linha ativa o produto some da busca da loja.';
25	COMMENT ON TABLE public.produto_legacy_mapping IS 'Mapeamento de produtos legados (produtos.id antigo) para o respectivo produto_master_id, por loja.';
26	COMMENT ON TABLE public.produto_sales_mapping IS 'Mapeia nomes/códigos de produto do PDV/vendas para produto_master_id, com status de conferência do match.';
27	COMMENT ON TABLE public.produto_aliases IS 'Apelidos/sinônimos de produtos aprendidos pelo matcher da requisição manual (fuzzy match), com contador de uso.';
28	COMMENT ON TABLE public.historico_vendas IS 'Histórico diário de vendas por produto e loja (qtd, valor, dia da semana). Base para forecast/DRP.';
29	COMMENT ON TABLE public.ncm_produtos IS 'Cadastro de NCM (classificação fiscal) e custo por produto/loja, usado em notas e tributação.';
30	COMMENT ON TABLE public.pronta_entrega_stock IS 'Estoque de pronta-entrega exposto na loja (produto, quantidade, validade, localização) para venda imediata.';
31	COMMENT ON TABLE public.pronta_entrega_logs IS 'Log de ações na pronta-entrega (entradas, baixas, ajustes) por usuário e loja.';
32	
33	-- requisições (lojas pedem à fábrica) & separação
34	COMMENT ON TABLE public.requisicoes IS 'Requisições de mercadoria que as lojas fazem à fábrica (cabeçalho: solicitante, preparador, lojas, datas, status, pipeline).';
35	COMMENT ON TABLE public.requisicoes_itens IS 'Itens de uma requisição (produto, qtd solicitada/enviada/recebida, separação, lote, validade).';
36	COMMENT ON TABLE public.requisition_pipelines IS 'Pipeline (workflow) de execução de uma requisição com etapas e coordenador. Fluxo estruturado de separação.';
37	COMMENT ON TABLE public.pipeline_funcionarios IS 'Funcionários alocados a cada etapa de um requisition_pipeline (papel e etapa atual).';
38	COMMENT ON TABLE public.pipeline_etapa_logs IS 'Log de ações/transições por etapa do requisition_pipeline (auditoria do workflow de separação).';
39	COMMENT ON TABLE public.pipeline_separacao_itens IS 'Itens separados por colaborador dentro de uma etapa do requisition_pipeline (qtd separada, status).';
40	COMMENT ON TABLE public.active_sessions IS 'Sessões de separação digital colaborativa em tempo real (cabeçalho: lojas, datas, status, expiração).';
41	COMMENT ON TABLE public.active_session_items IS 'Itens de uma sessão de separação digital (qtd solicitada/enviada, separado, bip de etiqueta QR).';
42	COMMENT ON TABLE public.active_review_sessions IS '(?) Sessões de conferência/revisão de separação ativas (cabeçalho temporário com expiração).';
43	COMMENT ON TABLE public.digital_separations IS 'Separações digitais (registro consolidado de uma sessão de separação concluída).';
44	COMMENT ON TABLE public.digital_separation_items IS 'Itens de uma separação digital (snapshot dos itens separados a partir da sessão).';
45	COMMENT ON TABLE public.digital_separation_users IS 'Usuários participando de uma separação digital colaborativa (presença em tempo real, cor de identificação).';
46	COMMENT ON TABLE public.expedicoes IS 'Expedições/rotas de entrega (Torre de Controle): agendamento, veículo, motorista, status.';
47	COMMENT ON TABLE public.expedicao_logs IS 'Log de eventos de uma expedição (saída, parada, entrega) vinculado a requisições. Timeline da Torre de Controle.';
48	
49	-- produção diária & PCP
50	COMMENT ON TABLE public.daily_production IS 'Produção diária registrada (produto, quantidade, data). loja_id NULL = fábrica (produção centralizada).';
51	COMMENT ON TABLE public.daily_production_products IS 'Produtos elegíveis para registro de produção diária por loja (lista da tela de produção).';
52	COMMENT ON TABLE public.daily_production_exclusions IS 'Produtos excluídos da lista de produção diária de uma loja.';
53	COMMENT ON TABLE public.weekly_production_plan IS 'Plano semanal de produção por loja/produto: demanda calculada, ajuste manual e produção final.';
54	COMMENT ON TABLE public.insumos IS 'Insumos/matérias-primas para produção: unidades de compra/produção, fatores de conversão e correção, custo, alérgenos.';
55	COMMENT ON TABLE public.fichas_tecnicas IS 'Fichas técnicas (receitas/BOM) de produtos: versão, rendimento, fator de rendimento, custo calculado.';
56	COMMENT ON TABLE public.ficha_tecnica_itens IS 'Itens de uma ficha técnica: insumo, sub-ficha (semi-acabado) ou produto, com quantidade, unidade e custo.';
57	COMMENT ON TABLE public.ficha_tecnica_etapas IS 'Etapas do processo produtivo de uma ficha técnica (ordem, setor, duração, temperatura, instruções).';
58	COMMENT ON TABLE public.ordens_producao IS 'Ordens de produção (OP): quantidades planejada/produzida/perdida, custos previsto/real, variância, lote e validade.';
59	COMMENT ON TABLE public.op_insumos IS 'Consumo de insumos por ordem de produção (qtd prevista x consumida, custo unitário e total).';
60	COMMENT ON TABLE public.op_perdas IS 'Perdas registradas por etapa dentro de uma ordem de produção (categoria, quantidade).';
61	COMMENT ON TABLE public.recipe_canvas_positions IS 'Posições (x,y) dos nós no canvas visual do construtor de fichas técnicas, por workspace.';
62	
63	-- encomendas & eventos
64	COMMENT ON TABLE public.encomendas IS 'Encomendas de clientes (delivery/retirada) com cliente, itens, entrega, pagamento e recorrência. Pode ter origem na Noaa.';
65	COMMENT ON TABLE public.eventos IS 'Eventos comerciais (feiras, ações externas) com data, local, responsável, faturamento e recorrência.';
66	COMMENT ON TABLE public.eventos_produtos IS 'Produtos enviados/separados para um evento (qtd enviada, retorno, perda, verificação).';
67	COMMENT ON TABLE public.eventos_custos IS 'Custos lançados em um evento (descrição, valor, tipo, anexo).';
68	COMMENT ON TABLE public.eventos_anexos IS 'Anexos/arquivos vinculados a um evento.';
69	COMMENT ON TABLE public.eventos_transacoes IS 'Transações financeiras (receitas/despesas) de um evento com categoria e comprovante.';
70	COMMENT ON TABLE public.eventos_perdas IS 'Perdas de produto registradas em um evento (produto, quantidade, motivo).';
71	COMMENT ON TABLE public.eventos_esocial IS 'Eventos eSocial gerados para um funcionário (XML, status de transmissão, resposta). Módulo RH.';
72	COMMENT ON TABLE public.orcamentos_gerados IS 'Orçamentos gerados para clientes (itens em JSON, valor total, desconto).';
73	COMMENT ON TABLE public.event_changelogs IS 'Changelog/auditoria de alterações em entidades de eventos e encomendas (ação, descrição, detalhes, autor).';
74	COMMENT ON TABLE public.acoes_marketing IS 'Ações de marketing com saída de produtos (degustação, cupom, embaixador, brinde, ação promocional etc.), com valor estimado e verificação.';
75	
76	-- logística (calendários/agenda)
77	COMMENT ON TABLE public.logistica_events IS '(?) Eventos de agenda logística simples (título, janela de tempo, loja). Provável modelo antigo de calendário.';
78	COMMENT ON TABLE public.logistica_calendarios IS 'Calendários da agenda de logística (nome, cor, padrão).';
79	COMMENT ON TABLE public.logistica_eventos IS 'Eventos da agenda de logística vinculados a um calendário (início/fim, dia inteiro, local).';
80	
81	-- financeiro: contas, cofre/livro caixa, NF, conciliação
82	COMMENT ON TABLE public.contas_pagar_receber IS 'Contas a pagar e a receber (tipo=pagar/receber), com vencimento, pagamento, parcelas, origem e vínculo a NF/fornecedor/conta bancária.';
83	COMMENT ON TABLE public.contas_pagar_receber_parcelas IS 'Parcelas de uma conta a pagar/receber (número, valor, vencimento, pagamento, juros, conta bancária).';
84	COMMENT ON TABLE public.movimentacoes_financeiras IS 'Lançamentos do Livro Caixa / Cofre por loja (entrada/saída), com categoria, forma de pagamento e responsável.';
85	COMMENT ON TABLE public.cofre_transferencias IS 'Transferências de valores entre cofres de lojas, ligando a movimentação de saída e a de entrada geradas.';
86	COMMENT ON TABLE public.custos_fixos IS 'Custos fixos mensais por loja, agrupados (grupo/item) e referenciados ao mês de competência.';
87	COMMENT ON TABLE public.notas_fiscais IS 'Notas fiscais de compra/entrada (fornecedor, valor, vencimento, forma de pagamento), com imagem para OCR. is_esboco=rascunho.';
88	COMMENT ON TABLE public.itens_nota_fiscal IS 'Itens de uma nota fiscal (produto, quantidade, valor unitário, subtotal), podendo vincular insumo.';
89	COMMENT ON TABLE public.notas_transferencia IS 'Notas de transferência entre lojas (ex.: Momma Doces). NÃO é nota fiscal/financeiro — apenas movimentação de mercadoria.';
90	COMMENT ON TABLE public.itens_nota_transferencia IS 'Itens de uma nota de transferência entre lojas (produto, quantidade, valor unitário, subtotal).';
91	COMMENT ON TABLE public.bank_accounts IS 'Contas bancárias por loja (banco, agência, conta, saldo inicial/atual) para conciliação financeira.';
92	COMMENT ON TABLE public.bank_transactions IS 'Transações bancárias (extrato), em geral importadas de OFX. Marcadas como conciliadas ao casar com lançamentos.';
93	COMMENT ON TABLE public.ofx_imports IS 'Importações de arquivos OFX de extrato bancário (período, contagem, totais de crédito/débito).';
94	COMMENT ON TABLE public.credit_cards IS 'Cartões de crédito por loja (bandeira, limite, dias de fechamento/vencimento).';
95	COMMENT ON TABLE public.credit_card_invoices IS 'Faturas mensais de cartão de crédito (mês de referência, valor, vencimento, pagamento).';
96	COMMENT ON TABLE public.credit_card_transactions IS 'Transações/lançamentos de cartão de crédito (descrição, valor, parcelas), vinculáveis a fatura e NF.';
97	COMMENT ON TABLE public.financial_records IS 'Registros financeiros consolidados por grupo/subgrupo de categoria e loja. Fonte da DRE/P&L (receita x despesa).';
98	COMMENT ON TABLE public.financial_entries IS '(?) Lançamentos financeiros por competência/unidade (unit_slug) e categoria. Tabela aparenta ser legada/pouco usada no app.';
99	COMMENT ON TABLE public.financial_accounts IS '(?) Contas financeiras (a pagar/receber) modelo alternativo com competência e vencimento por loja. Pouco/não populada.';
100	COMMENT ON TABLE public.financial_account_attachments IS 'Anexos vinculados a uma financial_accounts (arquivo, tipo, tamanho).';
101	COMMENT ON TABLE public.financial_categories IS 'Categorias financeiras configuráveis (tipo, categoria-pai, ordem de exibição).';
102	COMMENT ON TABLE public.financial_payroll_entries IS 'Lançamentos de folha de pagamento por loja/mês (salário, horas extras, encargos, líquido).';
103	COMMENT ON TABLE public.financial_budget_targets IS 'Metas orçamentárias por grupo/subgrupo de categoria, período, cenário e loja (orçado vs realizado).';
104	COMMENT ON TABLE public.financial_kpi_definitions IS 'Definições de KPIs financeiros (código, fórmula/lógica, formato, meta).';
105	COMMENT ON TABLE public.financial_forecasts IS 'Previsões financeiras por métrica/data (valor previsto, limites e confiança), por loja.';
106	COMMENT ON TABLE public.financial_audit_log IS 'Trilha de auditoria das tabelas financeiras (tabela, registro, ação, dados antes/depois, autor).';
107	COMMENT ON TABLE public.exchange_rates IS 'Taxas de câmbio por data (moeda base/alvo). Auxiliar para conversões financeiras.';
108	
109	-- financeiro: razão contábil (account_*) e gerencial/tributário (finance_*)
110	COMMENT ON TABLE public.account_accounts IS 'Plano de contas contábil (código, nome, tipo de conta). Núcleo do razão contábil estilo Odoo.';
111	COMMENT ON TABLE public.account_journals IS 'Diários contábeis (ex.: vendas, compras, caixa) com conta padrão. Agrupam lançamentos por tipo.';
112	COMMENT ON TABLE public.account_moves IS 'Lançamentos contábeis (cabeçalho do assento): data, diário, estado, parceiro, valor total, loja.';
113	COMMENT ON TABLE public.account_move_lines IS 'Linhas de lançamento contábil (débito/crédito por conta), com conciliação, subconta gerencial e centro de custo.';
114	COMMENT ON TABLE public.account_assets IS 'Ativos imobilizados para depreciação (valor, vida útil, método, estado), por loja.';
115	COMMENT ON TABLE public.finance_mgmt_groups IS 'Grupos da estrutura financeira gerencial (DRE gerencial) — nível mais alto.';
116	COMMENT ON TABLE public.finance_mgmt_accounts IS 'Contas gerenciais dentro de um grupo gerencial (nível intermediário da DRE gerencial).';
117	COMMENT ON TABLE public.finance_mgmt_subaccounts IS 'Subcontas gerenciais (nível folha da DRE gerencial): natureza, conta contábil e conjunto tributário padrão.';
118	COMMENT ON TABLE public.finance_cost_centers IS 'Centros de custo para rateio gerencial nos lançamentos contábeis.';
119	COMMENT ON TABLE public.finance_category_mgmt_map IS 'Mapeia categorias de origem (ex.: PDV, contas) para subcontas gerenciais (de->para da classificação financeira).';
120	COMMENT ON TABLE public.finance_payment_methods IS 'Métodos de pagamento configuráveis usados no razão contábil/lançamentos.';
121	COMMENT ON TABLE public.finance_document_types IS 'Tipos de documento configuráveis para lançamentos contábeis (ex.: NF, recibo).';
122	COMMENT ON TABLE public.finance_tax_families IS 'Famílias de tributos (ex.: ICMS, PIS, COFINS, ISS) com escopo de aplicação.';
123	COMMENT ON TABLE public.finance_tax_rates IS 'Alíquotas por família de tributo, com vigência, UF, regime e flags de recuperável/dedutível.';
124	COMMENT ON TABLE public.finance_tax_posting_rules IS 'Regras de contabilização por família de tributo (contas de recuperação, a pagar, dedução, despesa).';
125	COMMENT ON TABLE public.finance_tax_sets IS 'Conjuntos tributários (combinações de famílias/alíquotas) reutilizáveis, por escopo.';
126	COMMENT ON TABLE public.finance_tax_set_items IS 'Itens de um conjunto tributário (família + alíquota, em sequência).';
127	
128	-- Degust POS
129	COMMENT ON TABLE public.degust_stores IS 'Mapeamento entre lojas do POS Degust (franquia/loja) e a loja_id interna do Gidape.';
130	COMMENT ON TABLE public.degust_product_mapping IS 'Mapeia produtos do Degust (código/nome) para produto_master_id, com multiplicador de quantidade e tipo de match.';
131	COMMENT ON TABLE public.degust_vendas_diarias IS 'Cache de vendas diárias do Degust por loja/produto (quantidade, valor, nº transações).';
132	
133	-- funcionários / RH
134	COMMENT ON TABLE public.cargos IS 'Cargos/funções do RH (área, piso salarial de referência, código CCT). Módulo Funcionários.';
135	COMMENT ON TABLE public.employees IS 'Cadastro de funcionários (dados pessoais, contratuais, salário, jornada, loja, cargo, status de admissão/desligamento).';
136	COMMENT ON TABLE public.contratos IS 'Contratos de trabalho do funcionário (tipo, datas, prorrogações, cláusulas de experiência CLT).';
137	COMMENT ON TABLE public.experiencia_decisoes IS 'Decisões no período de experiência (prorrogar/efetivar/encerrar) ligadas a contrato e funcionário.';
138	COMMENT ON TABLE public.employee_audit_log IS 'Trilha de auditoria de alterações em funcionários (campo alterado, valores antes/depois, autor, IP).';
139	COMMENT ON TABLE public.employee_history IS 'Histórico effective-dated de mudanças de funcionário (cargo, salário, loja) com data de vigência.';
140	COMMENT ON TABLE public.ferias_periodos IS 'Períodos aquisitivos de férias por funcionário (datas, vencimento, limite de gozo, dias de direito/gozados). Criados por trigger.';
141	COMMENT ON TABLE public.ferias_marcacoes IS 'Marcações de férias dentro de um período aquisitivo (datas, dias, aprovação, PDF de aviso assinado).';
142	COMMENT ON TABLE public.metodos_punitivos IS 'Medidas disciplinares (advertências e suspensões) por funcionário, com PDFs gerado/assinado e status.';
143	COMMENT ON TABLE public.notificacoes_master IS 'Notificações para o master/RH (férias, punitivos, desligamentos pendentes). Consumidas em tempo real pelo sino e banner.';
144	COMMENT ON TABLE public.lgpd_solicitacoes IS 'Solicitações LGPD de titulares (acesso/correção/exclusão de dados), com prazo e resposta. Vinculadas a funcionário/usuário.';
145	COMMENT ON TABLE public.pesquisa_saida IS 'Entrevista de desligamento (exit interview): motivo de saída e notas de satisfação por funcionário.';
146	COMMENT ON TABLE public.pesquisa_clima_ciclos IS 'Ciclos de pesquisa de clima organizacional (período, loja, ativo).';
147	COMMENT ON TABLE public.pesquisa_clima_respostas IS 'Respostas anônimas (user_hash) a um ciclo de pesquisa de clima, com notas de satisfação.';
148	COMMENT ON TABLE public.freelancers IS 'Cadastro de freelancers recorrentes (valor da diária, chave PIX, status), por loja.';
149	COMMENT ON TABLE public.freelancer_work_days IS 'Dias trabalhados por um freelancer cadastrado (data, valor da diária, local/setor), por loja.';
150	COMMENT ON TABLE public.freelancer_avulso_work_days IS 'Dias trabalhados por freelancer avulso (não cadastrado), informado pelo nome, com valor da diária e local.';
151	
152	-- usuários, permissões, sistema
153	COMMENT ON TABLE public.usuarios IS 'Usuários do bot Telegram (legado), identificados por telegram_id. Distinto de profiles/auth.users do app.';
154	COMMENT ON TABLE public.profiles IS 'Perfil do usuário do app (vinculado a auth.users): nome, role, loja padrão, aprovação e permissões de troca de loja.';
155	COMMENT ON TABLE public.user_roles IS 'Papéis/roles do sistema (admin, gerente, operação etc.) com nome técnico e permissão de troca de loja.';
156	COMMENT ON TABLE public.permissions IS 'Permissões granulares por módulo, atribuídas a roles via role_permissions.';
157	COMMENT ON TABLE public.role_permissions IS 'Tabela de junção entre roles e permissões (quais permissões cada papel possui).';
158	COMMENT ON TABLE public.user_role_assignments IS 'Atribuição de roles a usuários (modelo multi-role; relaciona auth.users a user_roles).';
159	COMMENT ON TABLE public.user_admins IS 'Lista de usuários administradores (auth.users marcados como admin do sistema).';
160	COMMENT ON TABLE public.user_approvals IS 'Registro de aprovação de novos usuários (quem aprovou, quando, notas).';
161	COMMENT ON TABLE public.user_stores IS 'Vínculo usuário-loja (lojas que o usuário pode acessar; is_default = loja padrão). Modelo multi-loja por usuário.';
162	COMMENT ON TABLE public.user_preferences IS 'Preferências do usuário (notificações por email/push, tema escuro).';
163	COMMENT ON TABLE public.subscriptions IS '(?) Assinaturas Stripe (plano, período, status). Provável estrutura de SaaS, ainda não em uso (0 linhas).';
164	COMMENT ON TABLE public.configuracoes_sistema IS 'Configurações chave-valor do sistema (chave única, valor, tipo, categoria).';
165	COMMENT ON TABLE public.system_announcements IS 'Comunicados/novidades do sistema exibidos aos usuários (versão, categoria, prioridade, CTA, roles-alvo).';
166	COMMENT ON TABLE public.user_announcement_reads IS 'Controle de leitura/dispensa de comunicados por usuário (lido, CTA clicado, dispensado).';
167	COMMENT ON TABLE public.user_activity_log IS 'Log de atividade do usuário no app (tipo de evento, rota, elemento) para analytics de uso.';
168	COMMENT ON TABLE public.user_sessions IS 'Sessões de usuário no app (online, última atividade, rota atual, device) para presença e analytics.';
169	COMMENT ON TABLE public.chat_messages IS 'Histórico de mensagens do chat (legado/Telegram + web): role, conteúdo e tool_calls por sessão.';
170	COMMENT ON TABLE public.diagrams IS 'Diagramas (Mermaid) criados por usuário no editor interno de diagramas.';
171	COMMENT ON TABLE public.diagram_versions IS 'Versões/histórico de um diagrama Mermaid (texto e modelo de IA que gerou).';
172	
173	-- MIA (assistente IA interno)
174	COMMENT ON TABLE public.mia_action_log IS 'Log de ações executadas pela MIA no app (tipo, dados, sucesso, rota, resultado), com correlação a outcome.';
175	COMMENT ON TABLE public.mia_batch_operations IS 'Operações em lote da MIA (update/delete em massa) com snapshot para desfazer (undo). Inclui filtros e linhas afetadas.';
176	COMMENT ON TABLE public.mia_operation_previews IS 'Pré-visualizações de operações da MIA aguardando confirmação do usuário (preview -> confirma -> executa).';
177	COMMENT ON TABLE public.mia_sessions IS 'Sessões de conversa da MIA (canal, contadores de mensagens/tools/ações, device, título).';
178	COMMENT ON TABLE public.mia_tool_calls IS 'Registro de cada chamada de tool/ferramenta pela MIA (nome, domínio, duração, sucesso/erro).';
179	COMMENT ON TABLE public.mia_query_logs IS 'Log detalhado de cada consulta à MIA (texto, domínio, tools, rounds, latência, tokens, custo, satisfação).';
180	COMMENT ON TABLE public.mia_user_memory IS 'Memória per-user da MIA (Mirror): fatos aprendidos sobre o usuário com confiança, escopo e versionamento (superseded_by).';
181	COMMENT ON TABLE public.mia_user_patterns IS 'Perfil de padrões de uso por usuário (tools/intents/módulos/lojas/horários top, verbosidade, expertise). Recomputado periodicamente.';
182	COMMENT ON TABLE public.mia_feedback_signals IS 'Sinais de feedback inferidos das interações com a MIA (tipo, polaridade, evidência) para aprendizado.';
183	COMMENT ON TABLE public.mia_tool_permissions IS 'Permissões de cada tool da MIA por role e modo (ex.: read/write/disabled), com motivo.';
184	COMMENT ON TABLE public.mia_route_transitions IS 'Grafo agregado de transições entre rotas (from->to) com contagem. Aprende navegação típica para a MIA.';
