53	const WEEKDAY_MAP: Record<string, number> = {
54	  'domingo': 0, 'segunda': 1, 'segunda-feira': 1,
55	  'terça': 2, 'terça-feira': 2, 'terca': 2,
56	  'quarta': 3, 'quarta-feira': 3,
57	  'quinta': 4, 'quinta-feira': 4,
58	  'sexta': 5, 'sexta-feira': 5,
59	  'sábado': 6, 'sabado': 6
60	};
