62	export function getWeekdaysArray(dayInput: string | string[]): number[] {
63	  const inputs = Array.isArray(dayInput) ? dayInput : [dayInput];
64	  if (!inputs || inputs.length === 0) return [new Date().getDay()];
65	
66	  const uniqueDays = new Set(
67	    inputs
68	      .map(d => WEEKDAY_MAP[String(d).toLowerCase().trim()])
69	      .filter(d => d !== undefined)
70	  );
71	
72	  const result = Array.from(uniqueDays).sort((a, b) => a - b);
73	  return result.length > 0 ? result : [new Date().getDay()];
74	}
