80	export function getVolumeBasis(forecastTotal: number, last7dAvg: number): number {
81	  const v = Number(forecastTotal);
82	  if (Number.isFinite(v) && v > 0) return v;
83	  const fallback = Number(last7dAvg);
84	  return Number.isFinite(fallback) ? fallback : 0;
85	}
