87	export function classifyABC(
88	  items: Array<{ id: number; forecastTotal: number; last7dAvg: number }>
89	): ClassifiedItem[] {
90	  const sorted = [...items].sort(
91	    (a, b) => getVolumeBasis(b.forecastTotal, b.last7dAvg) - getVolumeBasis(a.forecastTotal, a.last7dAvg)
92	  );
93	
94	  const totalVolume = sorted.reduce(
95	    (sum, item) => sum + getVolumeBasis(item.forecastTotal, item.last7dAvg), 0
96	  );
97	
98	  let accumulatedVolume = 0;
99	
100	  return sorted.map(item => {
101	    const basis = getVolumeBasis(item.forecastTotal, item.last7dAvg);
102	    accumulatedVolume += basis;
103	    const cumulativeRatio = accumulatedVolume / (totalVolume || 1);
104	    const shareRatio = basis / (totalVolume || 1);
105	
106	    let classification: ABCClass = 'C';
107	    if (cumulativeRatio <= 0.8) classification = 'A';
108	    else if (cumulativeRatio <= 0.95) classification = 'B';
109	
110	    return { id: item.id, classification, cumulativeRatio, shareRatio };
111	  });
112	}
