1	-- DRP — Plano de Reposição
2	-- Adiciona idempotency_key em requisicoes + RPC drp_gerar_requisicoes (atomic, multi-loja).
3	--
4	-- Fluxo: frontend monta um payload com N planos (1 por loja) e chama esta função.
5	-- A função cria N requisicoes + M requisicoes_itens em UMA transação. Se idempotency_key
6	-- já existe, retorna o set existente sem duplicar (proteção contra double-click / retry).
7	
8	-- 1. Coluna idempotency_key
9	ALTER TABLE public.requisicoes
10	  ADD COLUMN IF NOT EXISTS idempotency_key TEXT;
11	
12	-- Índice unique parcial: só linhas com idempotency_key não-nulo são únicas
13	CREATE UNIQUE INDEX IF NOT EXISTS idx_requisicoes_idempotency_key
14	  ON public.requisicoes (idempotency_key)
15	  WHERE idempotency_key IS NOT NULL;
16	
17	COMMENT ON COLUMN public.requisicoes.idempotency_key IS
18	  'Chave de idempotência usada por geradores em lote (ex: DRP). Linhas DRP usam hash(user_id, data_chegada, loja, plan_signature).';
19	
20	-- 2. RPC: drp_gerar_requisicoes
21	-- Input shape:
22	--   {
23	--     "data_chegada": "2026-05-08",          -- DATE — vai pra requisicoes.data_recebimento
24	--     "data_durar_ate": "2026-05-12",        -- DATE — só metadata na observacao
25	--     "user_name": "João",                   -- TEXT — usado como solicitante e em logs
26	--     "preparador": "Fábrica",               -- TEXT — sempre "Fábrica" em V1
27	--     "plans": [
28	--       {
29	--         "loja_id": 2,
30	--         "loja_nome": "Asa Sul",            -- TEXT — vai pra requisicoes.loja_solicitante
31	--         "idempotency_key": "drp:abc123",   -- TEXT — único por (user, data, loja, plan)
32	--         "items": [
33	--           { "produto_master_id": 123, "nome_produto": "Bolo Cenoura",
34	--             "quantidade_solicitada": 10, "ordem": 0,
35	--             "observacao": "DRP" }
36	--         ]
37	--       }
38	--     ]
39	--   }
40	--
41	-- Output:
42	--   {
43	--     "requisicoes": [
44	--       { "id": 4321, "loja_id": 2, "loja_nome": "Asa Sul",
45	--         "qtd_itens": 24, "qtd_unidades": 142, "idempotent_hit": false }
46	--     ]
47	--   }
48	
49	CREATE OR REPLACE FUNCTION public.drp_gerar_requisicoes(plano JSONB)
50	RETURNS JSONB
51	LANGUAGE plpgsql
52	SECURITY DEFINER
53	SET search_path = public, pg_temp
54	AS $$
55	DECLARE
56	  v_user_id UUID := auth.uid();
57	  v_data_chegada DATE := (plano->>'data_chegada')::DATE;
58	  v_data_durar_ate DATE := (plano->>'data_durar_ate')::DATE;
59	  v_user_name TEXT := COALESCE(plano->>'user_name', 'Sistema');
60	  v_preparador TEXT := COALESCE(plano->>'preparador', 'Fábrica');
61	  v_plans JSONB := plano->'plans';
62	  v_plan JSONB;
63	  v_item JSONB;
64	  v_idem_key TEXT;
65	  v_loja_id INTEGER;
66	  v_loja_nome TEXT;
67	  v_existing_id INTEGER;
68	  v_new_req_id INTEGER;
69	  v_qtd_itens INTEGER;
70	  v_qtd_unidades INTEGER;
71	  v_results JSONB := '[]'::JSONB;
72	  v_result_item JSONB;
73	  v_obs TEXT;
74	  v_role_name TEXT;
75	BEGIN
76	  -- RBAC: só admin ou master
77	  SELECT ur.name INTO v_role_name
78	  FROM public.profiles p
79	  LEFT JOIN public.user_roles ur ON ur.id = p.role_id
80	  WHERE p.user_id = v_user_id;
81	
82	  IF v_role_name IS NULL OR LOWER(v_role_name) NOT IN ('admin', 'administrador', 'master') THEN
83	    RAISE EXCEPTION 'drp_rbac_denied: apenas admin/master pode gerar requisições via DRP (role=%)', v_role_name
84	      USING ERRCODE = '42501';
85	  END IF;
86	
87	  -- Validações estruturais
88	  IF v_data_chegada IS NULL THEN
89	    RAISE EXCEPTION 'drp_data_chegada_invalida' USING ERRCODE = '22023';
90	  END IF;
91	  IF v_data_durar_ate IS NULL THEN
92	    RAISE EXCEPTION 'drp_data_durar_ate_invalida' USING ERRCODE = '22023';
93	  END IF;
94	  IF (v_data_durar_ate - v_data_chegada) > 5 THEN
95	    RAISE EXCEPTION 'drp_horizonte_excede_validade: shelf-life uniforme 5d (chegada=%, durar_ate=%)',
96	      v_data_chegada, v_data_durar_ate USING ERRCODE = '22023';
97	  END IF;
98	  IF v_plans IS NULL OR jsonb_array_length(v_plans) = 0 THEN
99	    RAISE EXCEPTION 'drp_plans_vazio' USING ERRCODE = '22023';
100	  END IF;

